package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.TenantsSketchVO;

class TenantsSketchValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of tenants sketch of observed issue")
  void test_tenants_sketch_value_holder_assign_plain_value() {
    Object holder = new Object();
    TenantsSketchValueHolder<Object> value = new TenantsSketchValueHolder<>(holder);
    Assertions.assertSame(holder, value.tenantsSketch("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getTenantsSketchValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getTenantsSketch().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.tenantsSketchNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getTenantsSketchValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getTenantsSketch().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of tenants sketch of observed issue")
  void test_tenants_sketch_value_holder_assign_value_object() {
    Object holder = new Object();
    TenantsSketchValueHolder<Object> value = new TenantsSketchValueHolder<>(holder);
    TenantsSketchVO vo = TenantsSketchVO.from("one");
    Assertions.assertFalse(value.getTenantsSketchValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.tenantsSketch(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTenantsSketchValue().orElseThrow());
    Assertions.assertSame(holder, value.tenantsSketch(Optional.empty()));
    Assertions.assertFalse(value.getTenantsSketchValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.tenantsSketch(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTenantsSketchValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of tenants sketch of observed issue against the original")
  void test_tenants_sketch_value_holder_read() {
    Object holder = new Object();
    TenantsSketchValueHolder<Object> value = new TenantsSketchValueHolder<>(holder);
    TenantsSketchVO vo = TenantsSketchVO.from("one");
    TenantsSketchVO other = TenantsSketchVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getTenantsSketchValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTenantsSketch(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTenantsSketch(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.tenantsSketch(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTenantsSketch(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTenantsSketch(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of tenants sketch of observed issue")
  void test_tenants_sketch_value_holder_unset() {
    Object holder = new Object();
    TenantsSketchValueHolder<Object> value = new TenantsSketchValueHolder<>(holder);
    TenantsSketchVO vo = TenantsSketchVO.from("one");
    value.tenantsSketch(vo);
    Assertions.assertSame(holder, value.unsetTenantsSketchIfMatches("tenantsSketch_other"));
    Assertions.assertTrue(value.getTenantsSketchValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTenantsSketchIfMatches("tenantsSketch"));
    Assertions.assertFalse(value.getTenantsSketchValue().isPresent(),
        "The field name must clear the value");
    value.tenantsSketch(vo);
    Assertions.assertSame(holder, value.unsetTenantsSketch());
    Assertions.assertFalse(value.getTenantsSketchValue().isPresent(), "Unset must clear the value");
  }
}
